import {escapeHTML as e} from '../lib/common.mjs';

// Editorial HTML only, never user input. Each section has a stable link target.
const section=(id,title,html)=>({id,title,html});
const example=(input,output)=>`<div class="example-pair"><div><h3>Input</h3><pre>${e(input)}</pre></div><div><h3>Result</h3><pre>${e(output)}</pre></div></div>`;
export const textContent={
 'word-counter':{
  title:'Word Counter — Count Words & Characters | UtilityPilot',
  description:'Count words, characters with and without whitespace, sentences and lines. Check language-aware results and estimate reading time in your browser.',
  h1:'Word Counter',
  intro:'Count words in text, check characters with and without whitespace, and see sentence and line totals. Paste a draft, assignment or caption, choose its language, then select Count text to get the results.',
  guide:'unicode-counting',
  sections:[
   section('about','What is a word counter?',`<p>A word counter measures the amount of text in a passage. Use it to check a draft against a word limit, compare the lengths of revisions, or report the size of a writing project. UtilityPilot brings word count, character count and basic text statistics into one result, so you can check different requirements without pasting the same material into several tools.</p><p>The tool counts only what you put in the input box. It does not open a document, decide which parts of an assignment count toward a limit, or exclude quotations and references automatically. Copy the relevant text from your document first. A title pasted with the body becomes part of the total.</p>`),
   section('how-to','How to count words in text',`<ol><li>Paste or type the passage in Your input. For an assignment with exclusions, paste only the included sections.</li><li>Choose Text language. English is selected initially; select another available language when it better matches your text.</li><li>Leave reading speed at 200 words per minute or enter your own assumption. This changes the time estimate, not the word total.</li><li>Select Count text. Read Words in the result, then check any character or line requirement.</li><li>Copy result or Download to save the statistics. If you edit the input, select Count text again for a fresh result.</li></ol><p>Try sample input is a quick way to see the output before using your own writing. Reset clears the input and results. Counting runs in your browser; the text is not sent to a processing service, and this page does not automatically save your draft.</p>`),
   section('word-rules','How the word counter works: what counts as a word?',`<p>UtilityPilot uses the browser’s language-aware word segmenter and counts segments marked as word-like. It does not simply split text at every space. That distinction matters for punctuation, contractions and languages whose words are not consistently separated by spaces.</p><p>For example, in English, <code>Hello world!</code> has two words: the exclamation mark does not add another word. A standalone emoji contributes to the character total but is not itself counted as a word by this segmentation method. Numeric segments can count as words; a word total is not a count of dictionary entries.</p><p>Hyphens, apostrophes, mixed scripts and abbreviations can be treated differently by other counters. Language data can also vary across browser versions. If a school, publisher or submission system specifies a particular counter, use that system for the final decision. This counter makes its method visible so disagreements are easier to investigate.</p>`),
   section('word-examples','Word count examples',`${example('Hello world!','Words: 2\nCharacters (graphemes): 12\nCharacters without whitespace: 11\nUnicode code points: 12\nSentences: 1\nLines: 1\nEstimated reading seconds: 1')}<p>These results use English and 200 words per minute. Both letters and punctuation contribute to characters; the ordinary space contributes only to the total that includes whitespace.</p>${example('One two.\nThree four.','Words: 4\nCharacters (graphemes): 20\nCharacters without whitespace: 17\nSentences: 2\nLines: 2')}<p>The second example contains one real line break. It separates the lines and contributes a whitespace grapheme. A long sentence that merely wraps inside the input box still occupies one physical line.</p>`),
   section('character-counter','Character counter: count characters in text',`<p>A character counter measures smaller units than a word counter. UtilityPilot reports <strong>Characters (graphemes)</strong>, <strong>Characters without whitespace</strong> and <strong>Unicode code points</strong> together. Use the first two to inspect text length with and without whitespace, and the third when you need to understand how a symbol is represented.</p><h3>Characters with and without spaces</h3><p>The grapheme total includes letters, numbers, punctuation and whitespace. A grapheme cluster groups a base letter with its combining accent, or a joined emoji sequence, into one counting unit. “Visible character” is a useful shorthand, but the total also includes invisible whitespace such as line breaks.</p><p>The “without whitespace” result excludes grapheme clusters made entirely of JavaScript-recognized whitespace. This includes ordinary spaces, tabs, line breaks and non-breaking spaces. It is broader than subtracting only ordinary spaces. Punctuation remains included, and some invisible format characters are not whitespace under this rule.</p><h3>Character count examples</h3><ul><li><code>A B!</code>: 4 graphemes, 3 without whitespace, 4 code points.</li><li><code>é</code> written as an e plus a combining acute accent: 1 grapheme and 2 code points.</li><li><code>👨‍👩‍👧‍👦</code>: 1 grapheme and 7 code points in a browser that supports this emoji sequence.</li></ul><p>Application forms, captions, short descriptions and database fields can enforce different units. This tool does not report UTF-16 code units or encoded byte counts. Check the destination’s own counting rule before using a grapheme total to judge its limit. For a fuller explanation, read <a href="/guides/unicode-counting/">why word and character counts differ</a>.</p>`),
   section('word-vs-character','Word count vs character count',`<p>Word count is useful when the requirement concerns the amount of writing: an essay, article, report or assignment. Character count is useful when a field restricts text length at a smaller unit. Neither number can reliably be converted into the other using a fixed multiplier, because words vary in length and punctuation contributes characters without necessarily adding words.</p><p>For instance, <code>I am here.</code> and <code>Extraordinary ideas endure.</code> both contain three English words, but their character totals differ substantially. If your draft must satisfy both limits, inspect both results. Removing repeated spaces with <a href="/tools/text/text-cleaner/">Text Cleaner</a> can reduce characters without shortening the wording; editing a sentence changes its content as well as its size.</p>`),
   section('line-counter','Line counter: how UtilityPilot counts lines',`<p>Use the Lines result to count lines in text such as a checklist, pasted column or newline-separated list. The count follows actual line endings, not the number of visual rows shown on your screen. Changing the window width does not change it.</p><p>For counting lines, Windows CRLF and older CR line endings are treated as LF. Empty input has zero lines. A single final newline terminates the last line rather than creating another entry. Blank lines inside the text are included; a line containing only spaces still counts as a line.</p><ul><li><code>apple</code> has 1 line.</li><li><code>apple\\npear</code> has 2 lines.</li><li><code>apple\\npear\\n</code> still has 2 lines.</li><li><code>apple\\n\\npear</code> has 3 lines, including the blank one.</li></ul><p>Here <code>\\n</code> represents an actual newline, not two typed characters. To reduce repeated blank separators, see <a href="/tools/text/text-cleaner/#blank-lines">Text Cleaner’s blank-line options</a>. To count unique entries instead of all lines, first <a href="/tools/text/remove-duplicate-lines/">remove duplicate lines</a>. Physical lines are not CSV record counts: quoted CSV fields can contain newlines, so inspect tables with <a href="/tools/data/csv-viewer/">CSV Viewer</a>.</p>`),
   section('text-analysis','What this text analyzer measures',`<p>The counter provides seven basic metrics. They describe the pasted text without judging its quality, originality or meaning.</p><ul><li><strong>Words:</strong> language-aware word-like segments.</li><li><strong>Characters (graphemes):</strong> grouped character units, including whitespace.</li><li><strong>Characters without whitespace:</strong> grapheme units after excluding whitespace-only units.</li><li><strong>Unicode code points:</strong> individual Unicode values, including combining marks and joiners.</li><li><strong>Sentences:</strong> segments identified by the browser’s sentence segmenter; empty or whitespace-only input reports zero.</li><li><strong>Lines:</strong> physical lines using the terminator rules above.</li><li><strong>Estimated reading seconds:</strong> a calculation based on word count and your selected speed.</li></ul><p>Sentence boundaries around initials and abbreviations may differ from editorial expectations. The tool does not calculate readability grades, sentiment, keyword density or plagiarism scores. Use the metrics to check length and structure, then review the writing itself.</p>`),
   section('reading-time','How estimated reading time is calculated',`<p>The calculation is <strong>word count ÷ words per minute × 60</strong>, rounded up to a whole second. At 200 words per minute, 500 words give 150 seconds, or 2 minutes 30 seconds. Changing the assumption to 250 gives 120 seconds for the same text.</p><p>The default 200 is a setting, not a claim about every reader. Dense instructions, unfamiliar terminology and reading aloud can change the actual time. The estimate does not measure comprehension or include pauses for diagrams. Use it to compare drafts under the same assumption, rather than promise an exact completion time.</p>`),
   section('writing-workflows','Why word count matters in writing projects',`<p>For essays and assignments, check the brief for whether headings, references, footnotes or quotations are included. Paste the appropriate material, count it, and leave time to revise if it exceeds the limit. A counter cannot decide which exclusions your instructor intended.</p><p>For articles and blog posts, use word count to track a commissioned length or compare a revised draft with the original. Length alone does not establish completeness or search performance. A section earns its place by answering a reader’s question, not by increasing the total.</p><p>For social posts and short fields, start with the <a href="#character-counter">character-count explanation</a> and verify the result in the destination. For a document with suspicious spacing, <a href="/tools/text/text-cleaner/">clean the copied text</a> before counting if those spaces are accidental. Keep intentional paragraph breaks. To see exactly what an edit removed or added, <a href="/tools/text/text-diff/">compare the two drafts</a>.</p>`),
   section('limits','Input limits and common counting mistakes',`<p>The counter accepts up to 1 MiB of text, measured as UTF-8 input bytes. That is a processing limit, not a promise to accept one million visible characters: some characters need multiple bytes. Split larger documents into meaningful sections and keep a record of which sections you counted.</p><p>Do not count a title twice when combining section totals, mistake wrapped screen rows for line breaks, or assume the result updates while you type. Editing the input clears the old result; run the tool again. Copy and Download save the statistics, while your original text remains in the input until Reset or navigation.</p>`)
  ],
  faqs:[['Can I count words from a PDF or Word document?','Copy the relevant text into the input. This counter does not import PDF or Word files, read scanned images, or decide whether footnotes should count. Check the pasted text for missing sections and hard wraps.'],['Why does another word counter give a different result?','Counters can use different language rules and boundaries for punctuation, hyphens and contractions. Check that both received the same text and use the required submission system for the final count.'],['Does the character count include spaces?','Characters (graphemes) includes whitespace and punctuation. Characters without whitespace excludes whitespace-only graphemes, including ordinary spaces, tabs and newlines.'],['Can I use the counter without sending my draft to a server?','Yes. Counting runs locally in your browser. UtilityPilot does not upload the input to a processing service or automatically save the draft. Copy or download any result you need before leaving.']]
 },
 'case-converter':{
  title:'Title Case Converter, Uppercase & Lowercase | UtilityPilot',
  description:'Convert text to title case, uppercase, lowercase or sentence case. Choose a language, compare examples and review capitalization rules before copying.',
  h1:'Text Case Converter',
  intro:'Convert text to title case, uppercase, lowercase or sentence case in one place. Choose a case style and language, then review the result before copying it into a heading, label or document.',
  guide:'unicode-counting',
  sections:[
   section('how-to','How to convert text to a different case',`<ol><li>Paste the text to convert. Line breaks and punctuation can stay in the input.</li><li>Choose Case style: lowercase, UPPERCASE, Sentence case or Title Case. The initial selection is lowercase.</li><li>Choose the language that matches the text. Language affects letters such as Turkish dotted and dotless I.</li><li>Select Convert case. Review names, abbreviations and brand spellings in the output.</li><li>Copy result or Download the transformed text. To try another mode, change the selection and run the tool again.</li></ol><p>The original input remains available, so each run starts from that original text. The tool processes up to 1 MiB per input in your browser without uploading the text. It does not automatically apply the output to a document or overwrite a source file.</p>`),
   section('title-case','Title case converter: what is title case?',`<p>Title case uses capitals to distinguish words in a title or heading. Publications differ on which small words should remain lowercase. UtilityPilot’s Title Case option uses a simple, consistent rule: lowercase the text first, segment it into word-like units in the selected language, then uppercase the first character of each word-like unit when that character is a letter.</p><p>This produces an every-word style. Articles and connecting words such as “a”, “the”, “to” and “and” are capitalized too. The converter does not implement AP, APA, Chicago or another publication’s title rules, and it does not detect proper nouns or preserve acronyms automatically.</p><h3>Title case examples</h3>${example('a practical GUIDE to better TEXT','A Practical Guide To Better Text')}<p>The result is suitable as a starting point for a consistently capitalized heading. If your publication expects “to” to stay lowercase, make that editorial adjustment after conversion. In the same mode, <code>NASA and the moon</code> becomes <code>Nasa And The Moon</code>, so restore NASA when the acronym is intended.</p><p>Use title case for labels, slide headings or working titles when this mechanical style fits. For publication-ready titles, check the required style and names before using the result. A word beginning with a number is not treated as if it began with a letter; the tool does not scan ahead to find a later letter to capitalize.</p>`),
   section('sentence-case','Title case vs sentence case',`<p>Title Case capitalizes the start of each word-like segment. Sentence case first lowercases everything, then capitalizes an eligible letter at the start of the text or after sentence punctuation followed by whitespace. Supported punctuation boundaries are a period, exclamation mark or question mark, including their full-width forms.</p>${example('a practical GUIDE. another IDEA!','Title Case: A Practical Guide. Another Idea!\nSentence case: A practical guide. Another idea!')}<p>Sentence case is useful for ordinary prose that arrived in all capitals, but it is a heuristic. It cannot distinguish an abbreviation from a sentence ending, recognize a name halfway through a sentence, or infer every new sentence when punctuation is missing. A newline alone is not a sentence-punctuation boundary.</p><p>For <code>hello.world</code>, sentence mode produces <code>Hello.world</code>: there is no whitespace after the period. With <code>hello. world</code>, it produces <code>Hello. World</code>. This distinction helps explain results without attributing language understanding to a formatting tool.</p>`),
   section('uppercase','Uppercase converter: convert text to uppercase',`<p>Uppercase text uses capital forms of letters where the writing system has case. Select UPPERCASE to transform headings, short labels or a block of accidentally mixed capitalization. Spaces, line breaks, digits and punctuation remain in their positions.</p>${example('Launch code: ab-12','LAUNCH CODE: AB-12')}<p>Uppercasing uses the selected language’s Unicode case mapping. Some letters expand into more than one character; in German, <code>straße</code> becomes <code>STRASSE</code>. The output can therefore have a different character count even though the tool changes only capitalization.</p><p>Do not uppercase a password, token, case-sensitive identifier or URL path merely to make it look consistent. Its exact spelling may carry meaning. When the receiving field has a length limit, <a href="/tools/text/word-counter/#character-counter">check the converted character count</a>.</p>`),
   section('lowercase','Lowercase converter: convert text to lowercase',`<p>Lowercase mode replaces capital letters with their lowercase forms using the chosen language. It is useful for a consistent label style or a draft that was entered with Caps Lock on. It does not remove accents, punctuation, whitespace or duplicate words.</p>${example('A PRACTICAL Guide 2026','a practical guide 2026')}<p>Lowercase is the default mode. Select Convert case after pasting your text, then review the result. Lowercasing a name or acronym is intentional in this mode: the tool will not keep selected words capitalized on its own.</p><p>For list matching, changing the visible text may be unnecessary. <a href="/tools/text/remove-duplicate-lines/">Remove Duplicate Lines</a> can ignore letter case while retaining the original spelling of the chosen entry. That is often a better fit when you want case-insensitive matching rather than a permanently lowercase list.</p>`),
   section('language','How language changes capitalization',`<p>The same source text can convert differently under different language settings. With Turkish selected, lowercase <code>I</code> becomes <code>ı</code>, and uppercase <code>i</code> becomes <code>İ</code>. English uses a different pairing. Choose the language before processing rather than correcting unexpected letters afterward.</p><p>Not every writing system has upper and lower case, so parts of a multilingual passage may remain unchanged. The selected language applies to the input as a whole; the tool does not automatically switch languages word by word. Segmentation and mapping use the browser’s language data.</p>`),
   section('review','Review formatting and common mistakes',`<p>Capitalization is separate from spacing. If the original paste contains repeated spaces or broken paragraphs, use <a href="/tools/text/text-cleaner/#text-formatter">Text Cleaner’s formatting options</a>. To change a particular name or phrase across the result, use <a href="/tools/text/find-and-replace/">Find and Replace Text</a>. To inspect all edits between the original and converted text, use <a href="/tools/text/text-diff/">Text Diff</a>.</p><p>Check mixed-case brand names, initials, pronouns and technical abbreviations after converting. Once an acronym has been lowercased, a later title-case pass cannot reliably reconstruct it. Keep the original and make deliberate edits to the converted copy. Title capitalization alone does not make a heading clearer or more accurate.</p>`)
  ],
  faqs:[['Does Title Case keep short words lowercase?','No. This option capitalizes the initial letter of every word-like segment when it starts with a letter. It does not apply a list of minor words or a named publication style.'],['Does changing case remove formatting or spaces?','The converter changes capitalization, not spacing or layout. The input is plain text; use Text Cleaner for repeated spaces and line-break cleanup.'],['Why did my character count change?','Unicode case mappings can expand a letter into several characters, such as German ß becoming SS in uppercase. Recheck the character total if the destination has a limit.']]
 },
 'text-diff':{
  title:'Compare Text — Find Changes with Text Diff | UtilityPilot',
  description:'Compare two texts by lines or words. See labelled additions, removals and unchanged passages, with optional whitespace normalization and a text report.',
  h1:'Text Diff — Compare Two Texts',
  intro:'Compare text from two versions of a draft, message or configuration. Choose line or word comparison to see added, removed and unchanged passages, then copy or download the comparison report.',
  guide:'compare-lists-and-text',
  sections:[
   section('about','What does a text comparison tool do?',`<p>Text comparison identifies changes between two sequences of text. An earlier draft and an edited draft may look similar at a glance, but a diff makes insertions and deletions explicit. It is useful when you need to review an editor’s changes, check a rewritten paragraph or find which line changed in a small configuration.</p><p>UtilityPilot compares the text you paste, including its order. It does not interpret meaning, score similarity or establish whether one version is better. A change from “may” to “must” is reported as a text edit; deciding its significance remains part of your review.</p>`),
   section('how-to','How to compare two texts',`<ol><li>Paste the original or earlier text into Input A.</li><li>Paste the revised text into Input B. The direction matters: additions belong to B and removals come from A.</li><li>Select Lines for structural changes or Words for smaller wording edits.</li><li>Leave Normalize spaces and line endings off unless those differences should be ignored.</li><li>Select Compare text. Read the labelled result, then copy or download the text report if needed.</li></ol><p>The source inputs remain unchanged. If you change either input or an option, run the comparison again. An empty A can show the contents of B as additions; an empty B can show A as removals. Two empty inputs have no differences, which does not tell you whether the intended text was pasted.</p>`),
   section('method','How the text diff finds differences',`<p>The processor uses the bundled jsdiff sequence-comparison library. Lines mode compares line tokens. Words mode uses word-and-space tokens, keeping whitespace in the comparison rather than discarding it. This lets the result show textual edits without treating an entire paragraph as one indivisible item.</p><p>The algorithm produces a sequence of unchanged, removed and added passages. A replacement is represented by a removal and an addition, not a separate semantic “changed idea” operation. Repeated words or repeated lines can allow several valid ways of aligning the versions, so the particular highlighted path is not a record of the author’s keystrokes.</p><p>The tool has no character-by-character selector, ignore-case switch, automatic merge or plagiarism analysis. Capitalization is significant. To understand whether a punctuation or capitalization edit is intentional, read the original and revised passages around the highlight.</p>`),
   section('labels','Reading additions, removals and changed text',`<ul><li><strong>Added:</strong> text found in the revised sequence B that the comparison inserts.</li><li><strong>Removed:</strong> text from A that the comparison deletes.</li><li><strong>Unchanged:</strong> aligned text shared by the compared sequences.</li></ul><p>The result uses written labels as well as color. Copy result and Download produce a plain-text report with Added, Removed and Unchanged labels. This is a review report, not a patch file intended to be applied by Git or another patch utility.</p>${example('Input A: The draft is ready.\nInput B: The final draft is ready.','In Words mode, “final ” is added.\nIn Lines mode, the old line is removed and the revised line is added.')}<p>Words mode is useful for this small edit because it keeps the shared sentence visible around the inserted word. Lines mode is often clearer when several lines have been inserted or removed together.</p>`),
   section('whitespace','When to normalize whitespace',`<p>Enable Normalize spaces and line endings when repeated spaces or tabs are accidental noise. The comparison first converts CRLF and CR line endings to LF, collapses runs of ordinary spaces and tabs to one space, and removes the resulting ordinary space at each line edge.</p><p>It does not remove blank lines, collapse all Unicode whitespace or make the two raw inputs byte-identical. For example, “A” followed by two spaces and “B” can compare equal to “A B” with normalization enabled. A non-breaking space is not handled by that same ordinary-space rule.</p><p>Keep normalization off when indentation, tabs or exact spacing matter, especially in configuration or structured text. If you intentionally clean a document first, use <a href="/tools/text/text-cleaner/">Text Cleaner</a> on a copy, then compare the versions under matching rules.</p>`),
   section('uses','Practical text-comparison workflows',`<h3>Review an edited draft</h3><p>Place the submitted draft in A and the edited copy in B. Start with Words, read each removal and addition in context, and check names, dates and claims against the source material. A diff helps locate edits; it does not fact-check them.</p><h3>Check configuration or pasted data</h3><p>Use Lines with whitespace normalization disabled. Inspect changed keys, values and blank lines. This is a plain-text comparison, not a parser: equivalent JSON objects can look different because of member order or formatting. To make JSON indentation consistent first, use <a href="/tools/data/json-formatter/">JSON Formatter</a>, while keeping an original copy.</p><h3>Verify a repeated replacement</h3><p>After using <a href="/tools/text/find-and-replace/">Find and Replace Text</a>, compare the original with the output to check whether a short search also altered longer words. Whole-word matching can prevent some unintended replacements, but reviewing context is still useful.</p>`),
   section('lists','Text diff vs comparing lists',`<p>Text Diff answers “What changed in this sequence?” <a href="/tools/text/compare-lists/">Compare Lists</a> answers “Which unique entries are in both lists or only one?” These are different questions.</p><p>If A contains apple then pear, and B contains pear then apple, their membership is the same but their sequence differs. Choose Text Diff when order or repeated occurrences matter. Choose Compare Lists when finding shared or missing entries is the goal, and consult the <a href="/guides/compare-lists-and-text/">list comparison and text difference guide</a> for a worked example.</p>`),
   section('limits','Comparison limits and common mistakes',`<p>Each side accepts up to 256 KiB of UTF-8 text. The diff calculation is bounded to 1.5 seconds and a maximum edit length of 10,000. Very different inputs can reach the comparison limit even when their byte size is acceptable; compare corresponding smaller sections if that happens.</p><p>Paste text from PDF or Word documents yourself; this page does not extract document text, compare page layout, inspect images or preserve rich formatting. Keep A and B in a consistent earlier/later order. If the result says No differences found with normalization on, it refers to normalized text, not an exact raw-file identity check.</p>`)
  ],
  faqs:[['Does this compare the meaning of two texts?','No. It compares text sequences by lines or word-and-space tokens. It does not provide semantic similarity, authorship or plagiarism judgments.'],['Why does changing one word mark a whole line?','Lines mode uses whole lines as comparison units. Select Words and compare again to inspect smaller edits within that line.'],['Can I ignore capitalization?','There is no ignore-case option in Text Diff. Letter case is part of the comparison; whitespace normalization does not change it.']]
 },
 'text-cleaner':{
  title:'Text Cleaner — Remove Extra Spaces & Hard Wraps | UtilityPilot',
  description:'Clean up text online with precise spacing and line-break options. Trim line edges, collapse extra spaces, replace tabs and preserve paragraph breaks.',
  h1:'Text Cleaner',
  intro:'Clean up text copied from documents, emails or websites. Remove extra spaces, trim line edges and repair hard wraps with explicit options, while keeping the original paste beside the cleaned result.',
  guide:'clean-copied-text',
  sections:[
   section('about','What is a text cleaner?',`<p>A text cleaner repairs unwanted spacing and line breaks in plain text. A paste from a PDF can contain a newline after every visual row; a copied heading can contain repeated or non-breaking spaces. This tool lets you decide which of those characters should change before you reuse the text.</p><p>Cleanup does not rewrite sentences, fix grammar, repair OCR errors or recover the reading order of a document. It also does not strip HTML tags from source code. Pasting into the plain-text input does not retain fonts and colors, but literal markup such as <code>&lt;b&gt;word&lt;/b&gt;</code> remains text.</p>`),
   section('how-to','How to clean text online',`<ol><li>Paste the text into Your input. Keep the original source available.</li><li>Start with the defaults: replace non-breaking spaces, trim line edges and collapse repeated spaces. Line breaks are kept.</li><li>Select other operations only where they match the problem, such as replacing tabs or joining hard wraps.</li><li>Select Clean text. Inspect the output and the change counts for the selected operations.</li><li>Copy result or Download. If structure was lost, change the options and rerun from the unchanged input.</li></ol><p>Test a passage containing a heading, paragraph break and any meaningful indentation before processing a longer document. Up to 1 MiB of input is accepted, and cleanup runs locally in your browser.</p>`),
   section('whitespace','Remove whitespace: what each option changes',`<h3>Non-breaking spaces and tabs</h3><p>Replace non-breaking spaces converts U+00A0 to an ordinary space. This is enabled by default. Replace tabs with spaces converts each tab into one ordinary space, rather than reproducing its visual width; it starts off. Do not replace tabs in a tab-delimited table if they still separate fields.</p><h3>Leading, trailing and repeated spaces</h3><p>Trim line edges removes ordinary spaces and tabs from the start and end of each line. Collapse repeated spaces replaces runs of two or more ordinary spaces with one. Both start enabled. They do not implement a universal removal of every Unicode spacing character.</p><p>Collapse repeated spaces does not delete the single spaces between words. To <a href="/tools/text/find-and-replace/#remove-spaces">remove ordinary spaces from text entirely</a>, use literal Find and Replace with a space as Find and an empty replacement. Treat that as a different operation: joining “part one” into “partone” changes the text’s structure.</p><h3>Optional zero-width removal</h3><p>Remove zero-width characters deletes U+200B, U+200C, U+200D and U+FEFF. It starts off because joiners and non-joiners can affect scripts and emoji. An invisible character is not automatically unwanted. Use this option only when you have identified those characters as the source of a problem.</p>`),
   section('blank-lines','Remove blank lines or collapse extra blank lines?',`<p>The Collapse extra blank lines option reduces a run of three or more newline characters to two. In plain text, that keeps one empty line between two paragraphs. It is a way to reduce excessive paragraph spacing, not a complete remove-empty-lines command.</p><p>For example, <code>A\\n\\n\\nB</code> becomes <code>A\\n\\nB</code>. Here <code>\\n</code> stands for an actual line break. A single blank separator between A and B remains. Lines containing ordinary spaces or tabs can become empty first if Trim line edges is enabled; lines containing other characters may not.</p><p>Join all lines removes runs of line breaks by replacing each run with a space. That also removes the separation between nonblank lines, so it is not a way to delete blank entries while keeping a list intact. To inspect how many physical lines remain, use the <a href="/tools/text/word-counter/#line-counter">line count in Word Counter</a>.</p>`),
   section('line-breaks','Keep line breaks or repair hard wraps',`<p>Keep line breaks preserves the line structure after normalizing line endings. This is the default and is usually appropriate for addresses, poetry, source code and one-item-per-line lists.</p><p>Join hard wraps; keep paragraphs replaces a single newline between nonempty lines with a space. Two or more consecutive newline characters continue to separate paragraphs. It cannot infer that a heading or address deserves its own line if there is no blank line marking that boundary.</p><p>Join all lines replaces every consecutive run of newlines with one space. Use it only when one continuous text block is the desired result. For a simple list that needs commas rather than spaces, follow the <a href="/tools/text/find-and-replace/#comma-separated-list">comma-separated list workflow</a>.</p>`),
   section('examples','Cleaning text examples',`${example('  A  useful idea  ','A useful idea')}<p>The default options trim the edges and collapse the two spaces between A and useful. The words remain unchanged.</p>${example('A useful idea\nwrapped across lines.\n\nA new paragraph.','A useful idea wrapped across lines.\n\nA new paragraph.')}<p>The second example uses Join hard wraps; keep paragraphs. The single wrap is joined while the blank paragraph separator remains. If the original has no blank separators, this setting cannot reconstruct paragraphs from meaning. See the <a href="/guides/clean-copied-text/">copied-text cleanup guide</a> for a longer workflow.</p>`),
   section('method','How the text cleaner applies its rules',`<p>Operations run in this order: normalize CRLF and CR to LF; replace selected non-breaking spaces; replace selected tabs; trim line edges; collapse repeated ordinary spaces; collapse extra blank lines; join selected line breaks; remove selected zero-width characters.</p><p>Order matters. Replacing tabs first can create repeated spaces that the later collapse step removes. Joining lines happens after space collapsing, so it can introduce extra spaces if trimming was disabled or the source had unusual boundaries. Review the final output rather than assuming every sequence of options produces the same result.</p><p>The change counts report replacement matches, not characters removed. Trimming a run of five edge spaces is one match; zero-width removal counts the matched characters individually. A normalized line ending is also a change even when the result looks identical on screen.</p>`),
   section('text-formatter','Text formatter: format text online without changing the wording',`<p>As a plain-text formatter, this page handles spacing and line structure. It does not add fonts, bullets, numbered lists, indentation styles or rich document formatting. Use it to prepare copied paragraphs for an editor, normalize accidental spacing in labels, or tidy a simple list before another operation.</p><p>For capitalization, use the <a href="/tools/text/case-converter/">Text Case Converter</a>. For repeated entries, use <a href="/tools/text/remove-duplicate-lines/">Remove Duplicate Lines</a>. For specific unwanted strings, use <a href="/tools/text/find-and-replace/">Find and Replace Text</a>. These operations solve different problems and should not be applied automatically to every paste.</p>`),
   section('mistakes','Common text-cleaning problems',`<p>Tabs and leading spaces may encode columns or indentation; joining hard wraps can flatten an address; and zero-width joiners can change how an emoji or word is displayed. Select only the operations that fit the material. Check the result with <a href="/tools/text/text-diff/">Text Diff</a> if you need to see what changed, with whitespace normalization disabled so the cleanup edits remain visible.</p><p>A PDF may copy hyphenated words or text in the wrong column order. This cleaner does not know whether a hyphen belongs to a word or where the next column begins. Correct those issues explicitly rather than removing every hyphen or joining every line.</p>`)
  ],
  faqs:[['Can this remove all blank lines and preserve the other lines?','There is no dedicated option for that operation. Collapse extra blank lines keeps one empty separator; Join all lines joins the entire text. Choose only if that result matches your task.'],['Does this remove unwanted formatting from a document?','It works on the plain text you paste and changes selected whitespace. It does not edit a Word/PDF file, strip literal HTML markup or preserve rich document styling.'],['Why are some invisible characters still present?','Each option targets specific characters. The cleaner does not delete every invisible Unicode character because some are meaningful to scripts, emoji or formatting.']]
 },
 'remove-duplicate-lines':{
  title:'Remove Duplicate Lines — Keep Unique Entries | UtilityPilot',
  description:'Remove duplicate lines with exact, case-insensitive, trimmed or Unicode-normalized matching. Keep the first or last original entry and preserve order.',
  h1:'Remove Duplicate Lines',
  intro:'Remove duplicate lines from a pasted list while keeping the first or last occurrence. Choose exact matching or ignore case, surrounding whitespace and Unicode representation differences.',
  guide:'compare-lists-and-text',
  sections:[
   section('how-to','How to remove duplicate lines',`<ol><li>Paste one complete entry per line.</li><li>Leave matching options off for exact comparison, or choose the differences that should be ignored.</li><li>Select First or Last under Occurrence to keep.</li><li>Select Remove duplicates and check the retained and removed counts.</li><li>Copy result or Download the unique lines. The original input stays available.</li></ol><p>A repeated line is one complete entry that matches an earlier comparison key. The tool does not remove repeated words within a sentence, find similar names or merge partial entries. It accepts up to 1 MiB of text and runs in the browser.</p>`),
   section('matching','How duplicate lines are detected',`<p>Default matching is exact and case-sensitive. A line containing <code>Apple</code> differs from <code>apple</code>, and <code>apple </code> with a trailing space differs from <code>apple</code>. Punctuation also matters.</p><ul><li><strong>Ignore letter case:</strong> lowercase the comparison key using the tool’s English locale default. Original output spelling is retained.</li><li><strong>Ignore surrounding spaces:</strong> trim whitespace from the beginning and end of the comparison key. Internal spaces remain significant.</li><li><strong>Normalize Unicode (NFC):</strong> compare canonically normalized keys, allowing a precomposed accent to match its equivalent base-letter-plus-accent spelling.</li></ul><p>When enabled together, trimming happens first, NFC normalization second and lowercasing third. These operations change the key used to detect duplicates, not the surviving line. NFC does not remove accents, translate text or make all look-alike characters equal.</p>`),
   section('example','Duplicate line remover example',`${example('apple\npear\napple\nApple','Default, keep First:\napple\npear\nApple\n\nIgnore letter case, keep First:\napple\npear')}<p>The default removes one repeated line; case-insensitive matching removes two. Both keep the first apple spelling. If Ignore surrounding spaces is enabled and the first occurrence includes edge spaces, those spaces remain in the output. To change the visible text as well, <a href="/tools/text/text-cleaner/">clean the list</a> separately.</p>`),
   section('first-last','Keep the first or last occurrence',`<p>First retains the first matching entry and preserves the order of those first appearances. Last retains the final matching entry and preserves the order of the surviving last appearances. It does not keep the first position while swapping in the final spelling.</p>${example('apple\npear\nApple','Ignore letter case, keep First:\napple\npear\n\nIgnore letter case, keep Last:\npear\nApple')}<p>Choose the mode based on how the list was assembled. Last can retain a later spelling, but the tool has no timestamps and cannot prove the later line is more accurate. If chronology matters, confirm that the pasted order actually represents it.</p>`),
   section('lines','Blank lines, line endings and whitespace',`<p>The processor treats CRLF and CR as newline boundaries. One final newline is a terminator rather than an extra empty entry. Internal blank lines participate in duplicate matching, so repeated empty entries collapse to one retained blank entry.</p><p>A line of spaces and an empty line are different under exact matching. With Ignore surrounding spaces enabled, they share an empty comparison key, and the chosen original line survives. This behavior does not make the tool a remove-all-blank-lines utility. Use the <a href="/tools/text/word-counter/#line-counter">line counter</a> to inspect the result if blank entries affect the receiving workflow.</p>`),
   section('uses','Remove duplicate text online: useful list workflows',`<p>Deduplicate a repeated list of labels, pasted filenames or simple identifiers when one line represents one item. Start with exact matching for identifiers whose case might be significant. Enable broader matching only when those differences are irrelevant to your task.</p><p>After removing duplicates, <a href="/tools/text/sort-lines/">alphabetize the list</a> if you need a lookup-friendly order. Sorting is separate because the original sequence may matter. To find entries present in one list but missing in another, use <a href="/tools/text/compare-lists/">Compare Lists</a>; that is a membership comparison, not just deduplication.</p>`),
   section('limits','When line deduplication is the wrong tool',`<p>Do not use this on prose to remove duplicate words. A repeated sentence can be intentional, and two words on one line are not separate entries. There is no fuzzy matching, spelling correction or meaning-based grouping.</p><p>CSV records may contain quoted newlines, so a physical line is not always a complete row. Use <a href="/tools/data/csv-deduplicate/">CSV deduplication</a> for whole records or selected key columns. Always inspect the surviving entries before replacing an original list, especially when broader matching rules combine differently spelled values.</p>`)
  ],
  faqs:[['Does this sort the unique lines?','No. It preserves the order of the selected first or last occurrences. Use Alphabetize List & Sort Lines afterward if you need a sorted output.'],['Can it remove duplicate words in a paragraph?','No. Matching operates on complete lines. It does not tokenize prose into words or decide which repeated words should be removed.'],['Why did a retained entry still have spaces?','Ignore surrounding spaces changes the comparison key only. The retained output is the original line, including its spaces. Use Text Cleaner if those should also be removed.']]
 },
 'find-and-replace':{
  title:'Find and Replace Text — Literal Text Replacer | UtilityPilot',
  description:'Find and replace text with case and whole-word options. Replace repeated phrases, remove literal spaces or change simple list separators in your browser.',
  h1:'Find and Replace Text',
  intro:'Find a word, phrase or literal separator and replace every non-overlapping match. Choose case and whole-word options, leave the replacement empty to remove matches, or use actual line breaks to split and join a simple list.',
  guide:'clean-copied-text',
  sections:[
   section('how-to','How to find and replace text online',`<ol><li>Paste the text you want to edit into Your input.</li><li>Enter the exact text in Find. A word, phrase, punctuation character or actual line break can be a search.</li><li>Enter Replace with, or leave it empty to delete matching text.</li><li>Choose Ignore letter case or Match whole words only if required.</li><li>Select Replace matches. Read the match count and output before copying or downloading the result.</li></ol><p>Every run starts from the original input. Changing an option clears the previous result; select Replace matches again to recalculate. The Find field cannot be empty because that would not identify a specific piece of text to replace.</p>`),
   section('method','How finding and replacing works',`<p>The search is literal, global and non-overlapping. All matching occurrences in the original input are replaced in one pass. It does not search newly inserted replacement text again, so replacing a with aa does not expand indefinitely.</p><p>For example, finding <code>aa</code> in <code>aaa</code> matches the first two characters once; the overlapping pair starting at the second character is not another match. Finding a period searches for the period itself. Regular-expression syntax such as <code>.*</code> has no special meaning.</p><p>Replacement text is literal too. A dollar sign, backslash or string such as <code>$&amp;</code> is inserted as written, rather than interpreted as a captured group or matched-text reference. Use an actual newline in the multiline Find or Replace with field when you need a line break; typing backslash-n searches for or inserts those two characters.</p>`),
   section('case-words','Case sensitivity and whole-word matching',`<p>Matching distinguishes letter case by default: finding <code>red</code> will not change <code>Red</code>. Ignore letter case enables JavaScript’s Unicode-aware case-insensitive matching. It does not offer a language selector or normalize every visually similar spelling.</p><p>Match whole words only requires that the characters immediately outside the match are not letters, combining marks, numbers or underscores. Thus a whole-word search for <code>cat</code> matches <code>cat!</code> but not <code>catalog</code>, <code>cat2</code> or <code>cat_name</code>.</p><p>This is a boundary rule, not a dictionary or grammar check. Punctuation such as a hyphen can create a boundary. Leave whole-word mode off when replacing separators or ordinary spaces: adjacent letters would otherwise prevent many of those matches.</p>`),
   section('examples','Find and replace examples',`${example('red apple, red pear, red cherry','Find: red\nReplace with: green\nResult: green apple, green pear, green cherry\nMatches replaced: 3')}<p>A repeated label can be corrected consistently in one pass. Review a short search carefully: without whole-word matching, it can also appear inside a longer word. Use <a href="/tools/text/text-diff/">Text Diff</a> to compare the original and edited copies if the change spans a large passage.</p>`),
   section('remove-spaces','Remove spaces from text',`<p>To delete every ordinary space, put one space in Find and leave Replace with empty. Keep Match whole words only off. For <code>A B C</code>, this produces <code>ABC</code> with two replacements. Because the search field contains an invisible character, check the match count to confirm the intended search ran.</p><p>This does not remove tabs, non-breaking spaces or newlines unless you search for those actual characters in a separate pass. To collapse repeated spaces while retaining word separation, use <a href="/tools/text/text-cleaner/#whitespace">Text Cleaner’s whitespace options</a>. Removing every separator from ordinary prose usually joins words together, so use literal deletion only when that is intended.</p>`),
   section('comma-separated-list','Convert a list into comma-separated text',`<p>A comma-separated list places a comma between successive entries, such as <code>apple, pear, banana</code>. For a simple newline-separated list, the multiline Find and Replace controls can change those line breaks into commas without requiring another tool.</p><ol><li>Paste one item per line and remove unwanted blank entries or a final trailing newline from the input.</li><li>In Find, enter one actual line break by pressing Enter in the empty field.</li><li>In Replace with, enter a comma followed by a space, or just a comma if that is the required separator.</li><li>Leave whole-word matching off, select Replace matches and inspect the joined result.</li></ol>${example('apple\npear\nbanana','apple, pear, banana')}<p>This is literal separator replacement. A trailing newline becomes a trailing separator, and repeated blank lines become repeated separators. No blank items are filtered automatically.</p><h3>A simple list is not a CSV serializer</h3><p>If an item contains a comma, quote or embedded newline, replacing separators alone does not produce correctly quoted CSV. The tool does not add quotes or escape quotes inside values. For real tabular files, use the <a href="/tools/data/delimiter-converter/">CSV delimiter converter</a>, which parses fields and handles quoting. Do not convert a multiline CSV by globally replacing its newlines.</p>`),
   section('text-to-list','Text to list and list to text with a known separator',`<p>To turn a simple <code>apple;pear;banana</code> string into one item per line, find <code>;</code> and enter an actual line break in Replace with. If the source uses a semicolon followed by a space, find that exact two-character separator to avoid leaving a leading space on the next entry.</p><p>To join a list with pipes or another delimiter, find its actual newline and replace it with the required text, such as <code> | </code>. The same controls can join lines with a space. <a href="/tools/text/text-cleaner/#line-breaks">Text Cleaner</a> is more convenient when you need to distinguish hard wraps from paragraph breaks.</p><p>These workflows assume the delimiter does not also appear inside an item. There is no automatic delimiter detection, quoted-field handling, bullet generation or sentence-to-list analysis. After splitting a simple list, you can <a href="/tools/text/remove-duplicate-lines/">remove duplicate lines</a> or <a href="/tools/text/sort-lines/">sort its entries alphabetically</a>.</p>`),
   section('uses-limits','Practical uses and replacement limits',`<p>Use literal replacement to update a repeated product label in a draft, remove a known prefix, swap a simple delimiter or correct a specific repeated typo. A search for one name cannot determine whether every occurrence refers to the same person, so review matches in context.</p><p>The main input accepts up to 1 MiB; the Find and Replace with controls each allow up to 2,000 characters. Replacement output is bounded at 20 MiB. A very large expansion is rejected instead of generating an unbounded result. Copy and Download save only the transformed output, and processing stays in the browser.</p><p>An empty output can be a correct result if every input character matched a deletion. Zero matches can also be valid; check case, punctuation, invisible spaces and the whole-word setting before assuming the tool missed an occurrence.</p>`)
  ],
  faqs:[['Does this support regex?','No. Search and replacement are literal. Characters such as dots, asterisks and dollar signs keep their literal meanings.'],['How do I replace a line break?','Use an actual newline in the multiline Find field, and enter the desired separator in Replace with. Leave whole-word matching off. The two typed characters backslash and n are not interpreted as a newline.'],['Can I make a comma-separated list with quoted values?','Literal replacement does not quote or escape fields. It is suitable only for simple entries whose contents do not conflict with the separator. Use a record-aware CSV tool for structured data.']]
 },
 'compare-lists':{
  title:'Compare Lists — Find Shared & Missing Entries | UtilityPilot',
  description:'Compare two lists for shared items, entries only in A or B, and a combined unique list. Choose exact, case, whitespace or Unicode matching rules.',
  h1:'Compare Lists',
  intro:'Compare two lists to find shared and missing entries, or combine them into one unique list. Put one item per line and choose whether case, surrounding whitespace or Unicode spelling differences should affect matching.',
  guide:'compare-lists-and-text',
  sections:[
   section('about','Compare list membership, not document revisions',`<p>List comparison asks whether an entry appears in one collection, another collection or both. It is useful for checking a checklist against an inventory, comparing two exported columns of identifiers, or finding which labels still need to be added.</p><p>This tool treats each list as a set of unique entries. Reordering entries does not change membership, and repeating an item does not add another member. To compare wording, line order or repeated occurrences in two versions of a document, use <a href="/tools/text/text-diff/">Text Diff to compare text</a> instead.</p>`),
   section('how-to','How to compare two lists',`<ol><li>Paste one entry per line into Input A and Input B.</li><li>Choose matching rules. All ignore/normalization options start off, so exact matching is the default.</li><li>Choose Result to export: Shared, Only in A, Only in B or Union.</li><li>Select Compare lists. Check the group counts and duplicate totals in the result.</li><li>Copy or download the selected group. To export another group, change the selection and compare again.</li></ol><p>Up to 1 MiB is accepted per input. The browser processes both lists locally, and the original entries remain in the input boxes.</p>`),
   section('groups','Understanding shared, missing and combined entries',`<ul><li><strong>Shared:</strong> unique entries that occur in both A and B.</li><li><strong>Only in A:</strong> entries from A without a matching entry in B.</li><li><strong>Only in B:</strong> entries from B without a matching entry in A.</li><li><strong>Union:</strong> all unique entries from both lists.</li></ul><p>Only in A means missing from B; it does not mean the item is incorrect or should be deleted. Decide which list is the reference before interpreting the result. If A is empty, Only in B and Union contain B’s unique entries. An empty Shared result can simply mean the lists have no members in common.</p>`),
   section('example','List comparison example',`${example('Input A:\napple\npear\npear\n\nInput B:\npear\ncherry','Shared: pear\nOnly in A: apple\nOnly in B: cherry\nUnion: apple, pear, cherry\nDuplicates in A: 1\nDuplicates in B: 0')}<p>The commas in this explanation summarize the members; the actual exported group uses one entry per line. The repeated pear contributes to the duplicate count but does not appear twice in Shared or Union.</p>`),
   section('matching','Matching rules and preserved spelling',`<p>Default matching distinguishes case, edge whitespace and Unicode spellings. Ignore letter case lowercases comparison keys using the English locale default. Ignore surrounding spaces trims whitespace from each key. Normalize Unicode (NFC) makes canonically equivalent forms comparable, such as an accented letter represented in two equivalent ways.</p><p>The original spelling is preserved in the output. Shared and Only in A use A’s first matching occurrence and its order. Only in B uses B’s first occurrences. Union starts with A’s unique entries, then adds previously unseen entries from B. There is no option here to keep the last duplicate spelling.</p><p>Internal spaces and punctuation remain significant. NFC does not remove accents or merge all look-alike letters. Apply broader matching only when your task considers those differences irrelevant.</p>`),
   section('mistakes','Blank entries, repeated items and other common mistakes',`<p>Internal blank lines count as entries. One final newline is a terminator, not an extra item. If both lists contain an internal blank line, their Shared group may include an empty entry. With surrounding-whitespace matching enabled, a spaces-only entry can match an empty one.</p><p>A comma-separated row is one line, not several entries. For a simple delimiter-separated list, use <a href="/tools/text/find-and-replace/#text-to-list">Find and Replace to split the items</a> first. For CSV with quotes or multiline fields, use the <a href="/tools/data/csv-viewer/">data tools to inspect its records</a> before extracting a column.</p><p>Use <a href="/tools/text/remove-duplicate-lines/">Remove Duplicate Lines</a> when the task involves just one list or requires retaining the last occurrence. Use <a href="/tools/text/sort-lines/">Alphabetize List</a> after comparison when the output needs alphabetical order. The <a href="/guides/compare-lists-and-text/">comparison guide</a> explains why membership and sequence comparisons can return different answers for the same inputs.</p>`)
  ],
  faqs:[['Can identical members in a different order count as a match?','Yes. Membership ignores position. The output still follows the documented first-seen order. Text Diff is the appropriate tool if the reordered sequence matters.'],['Does Union keep duplicate copies from both lists?','No. It keeps one member per comparison key, using A’s first spelling where both lists contain a match.'],['Why is the output empty when some result counts are nonzero?','Copy and Download use the selected Result to export group. A different group may contain entries even when the selected group is empty.']]
 },
 'sort-lines':{
  title:'Alphabetize List — Sort Lines A to Z | UtilityPilot',
  description:'Alphabetize a list A–Z or Z–A. Sort lines naturally, numerically or by length, with language and case options. Preview and copy the reordered text.',
  h1:'Alphabetize List & Sort Lines',
  intro:'Alphabetize a list with one item per line, or choose natural, numeric or length sorting. Select the language and direction, then copy the reordered list without changing the text of its entries.',
  guide:'compare-lists-and-text',
  sections:[
   section('how-to','How to alphabetize a list',`<ol><li>Paste one item per line. An item can be a word, name, phrase or complete sentence.</li><li>Choose Alphabetical under Sort order and select the text language.</li><li>Leave Descending unchecked for A to Z. Check it for Z to A.</li><li>Enable Ignore letter case if capitalization should not distinguish entries.</li><li>Select Sort lines, inspect the output, then Copy result or Download.</li></ol><p>The tool sorts complete lines. It does not alphabetize the individual words within a sentence or automatically split comma-separated text into entries. For a simple delimiter-separated list, <a href="/tools/text/find-and-replace/#text-to-list">replace its separator with a line break</a> first.</p>`),
   section('alphabetical','How the alphabetize list tool works',`<p>Alphabetical sorting uses the selected language’s comparison rules through the browser’s collator. This is language-aware ordering rather than a raw character-code sort. Accents, punctuation, capitalization and mixed scripts can therefore produce a different order from a spreadsheet or a tool configured for another locale.</p><p>Ignore letter case makes case differences equal for comparison, while accent differences remain meaningful. The output preserves each original line’s spelling and surrounding spaces. Entries with equal comparison values keep their relative input order, including when Descending is selected. Sorting neither removes duplicates nor normalizes the text itself.</p>`),
   section('a-to-z','Sort a list A to Z or Z to A',`${example('pear\napple\nbanana','A to Z:\napple\nbanana\npear\n\nZ to A:\npear\nbanana\napple')}<p>These examples use Alphabetical and English, with Descending off or on. This is useful for a packing list, list of labels or directory entries when a predictable order helps you find items.</p><p>Reverse current order is different. It flips the pasted sequence without alphabetizing it: the input above becomes banana, apple, pear. Choose reverse only when the original sequence already carries an order you want to invert. The Descending checkbox has no additional effect in Reverse current order mode.</p>`),
   section('natural','Natural sorting for numbered names',`<p>Use Natural when your entries combine words and numbers. Digit runs are compared as numbers, so item2 comes before item10. Alphabetical mode compares their text forms and can place item10 before item2.</p>${example('item10\nitem2\nitem1','Natural:\nitem1\nitem2\nitem10\n\nAlphabetical:\nitem1\nitem10\nitem2')}<p>Natural order is useful for numbered filenames, chapters or labels. It does not parse dates, software versions or arbitrary identifiers into a specialized domain order. Confirm a few representative entries when your naming convention has punctuation, several number groups or leading zeros.</p>`),
   section('numeric-length','Numeric sorting and sorting by length',`<p>Numeric mode requires a finite decimal number on every line. Decimal fractions, signs and scientific notation are accepted. Currency symbols, thousands separators, localized decimal commas, hexadecimal values, blank lines and mixed text are rejected. Normalize those inputs deliberately before sorting.</p><p>Accepted numbers are compared from their decimal spellings without rounding long integer or fractional digits through ordinary floating-point arithmetic. For example, 9007199254740992 remains distinguishable from 9007199254740993. The original spelling is kept, so equivalent inputs such as 1 and 1.0 remain separate entries in their stable order.</p><p>Character length mode sorts by Unicode code points. That is not display width or grapheme count: a combined emoji or accented letter can use several code points. Use the <a href="/tools/text/word-counter/#character-counter">character counter explanation</a> if the distinction affects your list.</p>`),
   section('names','Alphabetizing names and titles',`<p>Names are sorted from the beginning of each complete line. “Ada Lovelace” is compared starting with Ada; the tool does not extract surnames. If your directory needs surname ordering, prepare consistently formatted entries such as “Lovelace, Ada” before pasting.</p><p>Titles keep their opening articles. “The Secret Garden” is sorted with its initial “The”; there is no ignore-articles switch. Bullets, numbering and leading spaces also remain part of the entry. Remove unwanted prefixes deliberately, or <a href="/tools/text/text-cleaner/">clean surrounding whitespace</a>, before sorting.</p>`),
   section('problems','Common list-sorting problems',`<p>If the entire input stays on one line, its items probably use commas or another separator instead of real newlines. Visual wrapping in the input box does not create separate entries. A final newline terminates the last entry; internal blank lines are entries and may move during sorting.</p><p>If repeated values remain, that is expected. Use <a href="/tools/text/remove-duplicate-lines/">Remove Duplicate Lines</a> before sorting when the desired output is unique. To find entries missing from another list without changing either sequence, use <a href="/tools/text/compare-lists/">Compare Lists</a>.</p><p>Do not sort physical lines from a CSV containing quoted multiline fields: that can separate parts of one record. Use <a href="/tools/data/csv-viewer/">CSV Viewer</a> to inspect the structure. This sorter accepts up to 1 MiB of input and runs locally; its output is plain text, not an automatically formatted spreadsheet.</p>`)
  ],
  faqs:[['Can I sort text alphabetically without changing its capitalization?','Yes. Sorting reorders complete lines and preserves their original text. Ignore letter case affects comparison, not the capitalization of the output.'],['Can I alphabetize by last name?','There is no surname-extraction option. Put the surname first on each line before sorting if that is the order you need.'],['Why are item10 and item2 in the wrong order?','Alphabetical mode compares text. Select Natural to compare number runs numerically, putting item2 before item10.']]
 }
};
